sed -i '/match \/appeals\/{appealId} {/i \    match \/support_chats\/{chatId} {\n      allow read: if isAuthenticated() && (isAdmin() || isSupport() || isEmployee() || isOwner(resource.data.userId));\n      allow write: if isAuthenticated();\n    }\n\n    match \/support_chats\/{chatId}\/messages\/{messageId} {\n      allow read: if isAuthenticated();\n      allow write: if isAuthenticated();\n    }\n' firestore.rules
